"use client";

import { Button } from "./button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "./dropdown-menu";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "./popover";
import { Switch } from "./switch";
import {
  ToggleGroup,
  ToggleGroupItem,
} from "./toggle-group";
import {
  AlignLeftIcon,
  ChevronDownIcon,
  LayoutGridIcon,
  ListOrderedIcon,
  RotateCcwIcon,
  Settings2Icon,
} from "lucide-react";
import type { ReactNode } from "react";

export type TableViewMode = "list" | "card";

export type TableViewMenuColumn = {
  id: string;
  label: string;
  icon?: ReactNode;
  visible: boolean;
};

export type TableViewMenuGroupOption = {
  value: string;
  label: string;
};

export type TableViewMenuProps = Readonly<{
  columns?: TableViewMenuColumn[];
  onToggleColumn?: (columnId: string) => void;
  groupByValue?: string;
  groupByOptions?: TableViewMenuGroupOption[];
  onChangeGroupBy?: (value: string) => void;
  view?: TableViewMode;
  onChangeView?: (view: TableViewMode) => void;
  onResetView?: () => void;
  onResetToStackRank?: () => void;
  viewHeading?: string;
  columnsHeading?: string;
}>;

function GroupByModeSelect({
  value,
  options,
  onChange,
}: Readonly<{
  value: string;
  options: TableViewMenuGroupOption[];
  onChange: (value: string) => void;
}>) {
  const selected = options.find((option) => option.value === value);

  return (
    <div className="flex flex-col px-4 pb-3">
      <div className="flex h-9 items-center justify-between">
        <span className="text-sm">Group by</span>
        <DropdownMenu>
          <DropdownMenuTrigger asChild>
            <Button className="h-7 text-xs" size="sm" variant="outline">
              {selected?.label ?? value}
              <ChevronDownIcon className="h-3.5 w-3.5" />
            </Button>
          </DropdownMenuTrigger>
          <DropdownMenuContent align="end">
            {options.map((option) => (
              <DropdownMenuItem
                key={option.value}
                onClick={() => onChange(option.value)}
              >
                {option.label}
              </DropdownMenuItem>
            ))}
          </DropdownMenuContent>
        </DropdownMenu>
      </div>
    </div>
  );
}

function ViewModeToggle({
  view,
  onChangeView,
}: Readonly<{
  view: TableViewMode;
  onChangeView: (view: TableViewMode) => void;
}>) {
  return (
    <div className="px-4 pt-2 pb-4">
      <ToggleGroup
        className="w-full"
        onValueChange={(value) => {
          if (value === "list" || value === "card") {
            onChangeView(value);
          }
        }}
        type="single"
        value={view}
        variant="outline"
      >
        <ToggleGroupItem className="h-7 flex-1 text-xs" value="list">
          <AlignLeftIcon className="h-3.5 w-3.5" />
          List
        </ToggleGroupItem>
        <ToggleGroupItem className="h-7 flex-1 text-xs" value="card">
          <LayoutGridIcon className="h-3.5 w-3.5" />
          Card
        </ToggleGroupItem>
      </ToggleGroup>
    </div>
  );
}

export function TableViewMenu({
  columns,
  onToggleColumn,
  groupByValue,
  groupByOptions,
  onChangeGroupBy,
  view,
  onChangeView,
  onResetView,
  onResetToStackRank,
  viewHeading = "View Options",
  columnsHeading = "Show/Hide Columns",
}: TableViewMenuProps) {
  const showViewToggle = view != null && onChangeView != null;
  const showGroupByMode =
    groupByValue != null &&
    groupByOptions != null &&
    groupByOptions.length > 0 &&
    onChangeGroupBy != null;
  const showColumnVisibility =
    columns != null && columns.length > 0 && onToggleColumn != null;
  const showOptionsHeading = showViewToggle || showGroupByMode;
  const showOptionsDivider = showOptionsHeading && showColumnVisibility;

  return (
    <Popover>
      <PopoverTrigger asChild>
        <Button className="h-8 shadow-none" size="sm" variant="outline">
          <Settings2Icon />
          View
        </Button>
      </PopoverTrigger>
      <PopoverContent align="end" className="w-72 p-0">
        {showOptionsHeading ? (
          <div className="px-4 pt-4 pb-2">
            <h4 className="font-semibold text-lg">{viewHeading}</h4>
          </div>
        ) : null}
        {showViewToggle ? (
          <ViewModeToggle onChangeView={onChangeView} view={view} />
        ) : null}
        {showGroupByMode ? (
          <GroupByModeSelect
            onChange={onChangeGroupBy}
            options={groupByOptions}
            value={groupByValue}
          />
        ) : null}
        {showOptionsDivider ? <div className="mx-4 border-t" /> : null}
        {showColumnVisibility ? (
          <>
            <div className="flex items-center justify-between px-4 pt-4 pb-2">
              <h4 className="font-semibold text-base">{columnsHeading}</h4>
            </div>
            <div className="flex flex-col divide-y px-4 pb-3">
              {columns.map((column) => (
                <div
                  className="flex cursor-pointer items-center justify-between py-3"
                  key={column.id}
                >
                  <span className="flex items-center gap-2 text-sm">
                    {column.icon}
                    {column.label}
                  </span>
                  <Switch
                    checked={column.visible}
                    id={`col-${column.id}`}
                    onCheckedChange={() => onToggleColumn(column.id)}
                  />
                </div>
              ))}
            </div>
          </>
        ) : null}
        {onResetToStackRank || onResetView ? (
          <>
            <div className="mx-4 border-t" />
            <div className="flex flex-col gap-1 px-4 py-3">
              {onResetToStackRank ? (
                <Button
                  className="h-7 w-full justify-start gap-2 text-muted-foreground text-xs"
                  onClick={onResetToStackRank}
                  size="sm"
                  variant="ghost"
                >
                  <ListOrderedIcon className="h-3.5 w-3.5" />
                  Reset to stack rank
                </Button>
              ) : null}
              {onResetView ? (
                <Button
                  className="h-7 w-full justify-start gap-2 text-muted-foreground text-xs"
                  onClick={onResetView}
                  size="sm"
                  variant="ghost"
                >
                  <RotateCcwIcon className="h-3.5 w-3.5" />
                  Reset view
                </Button>
              ) : null}
            </div>
          </>
        ) : null}
      </PopoverContent>
    </Popover>
  );
}
